<script>
  import { game, currentMatch, purchaseItem, continueFromShop } from '../store.js';
  import { SHOP_ITEMS } from '../engine/data.js';
  const ICONS={energy_drink:'⚡',tactical_upgrade:'▲',set_piece_drill:'⚑',super_sub:'↻',tactical_shift:'⇄',formation_tweak:'⌗',momentum_injector:'»',scout_report:'◉',double_session:'◆',morale_boost:'★'};
  $: items=Object.entries(SHOP_ITEMS);
  $: bought=new Set($game.purchasedItems||[]);
</script>
<div class="shop-shell">
  <header><div><span class="crest">S</span><div><small>BETWEEN MATCHES</small><strong>BACKROOM MARKET</strong></div></div><div class="morale"><small>TEAM MORALE</small><strong>★ {$game.morale}</strong></div></header>
  <main>
    <aside class="paper"><span class="kicker">MATCH REVIEW</span><h2>THE GAFFER'S DESK</h2><p>You beat the previous opponent. Spend morale on preparation before facing <b>{$currentMatch?.opponent}</b>.</p><div class="receipt"><small>ITEMS BOUGHT</small><strong>{bought.size}</strong></div><p class="note">Purchases are permanent for this run or apply to the next round as described.</p></aside>
    <section><div class="market-head"><div><span>NEXT FIXTURE</span><h1>{$currentMatch?.opponent}</h1></div><p>Choose upgrades, then return to the tactical room.</p></div><div class="items">{#each items as [id,item],i}<button class="item" class:bought={bought.has(id)} disabled={bought.has(id)||$game.morale<item.cost} on:click={()=>purchaseItem(id)}><div class="stripe"></div><span class="index">#{String(i+1).padStart(2,'0')}</span><b class="icon">{ICONS[id]||'◆'}</b><h3>{item.name}</h3><p>{item.desc}</p><div><strong>★ {item.cost}</strong><small>{bought.has(id)?'BOUGHT':$game.morale<item.cost?'NOT ENOUGH':'BUY ITEM'}</small></div></button>{/each}</div></section>
  </main>
  <footer><div><small>NEXT OPPONENT</small><strong>{$currentMatch?.opponent}</strong></div><p>{$game.shopMessage||'Preparation can turn a close tie.'}</p><button on:click={continueFromShop}>NEXT MATCH <b>→</b></button></footer>
</div>
<style>
  :global(body){overflow:hidden}.shop-shell{--paper:#d7d0bd;--orange:#e87c42;min-height:100vh;height:100vh;padding-bottom:78px;color:#eee6d6;background:radial-gradient(circle at 62% 0,rgba(84,126,91,.28),transparent 40%),linear-gradient(#111f17,#080e0a)}header{height:84px;padding:0 34px;display:flex;justify-content:space-between;align-items:center;background:#080e0a;border-bottom:1px solid #354139}header>div:first-child{display:flex;align-items:center;gap:12px}.crest{width:43px;height:49px;display:grid;place-items:center;clip-path:polygon(8% 0,92% 0,100% 70%,50% 100%,0 70%);background:var(--orange);color:#172018;font-family:var(--font-display)}header small{display:block;font-family:var(--font-display);font-size:.27rem;color:#738078}header strong{font-family:var(--font-display);font-size:.57rem}.morale{text-align:right}.morale strong{display:block;color:#e9a85d;font-size:.76rem;margin-top:5px}main{height:calc(100vh - 162px);width:min(1450px,calc(100% - 46px));margin:auto;display:grid;grid-template-columns:230px 1fr;gap:28px;padding:25px 0}.paper{align-self:start;color:#292b27;background:var(--paper);border-top:5px solid #b64d42;box-shadow:8px 10px 0 rgba(0,0,0,.2);padding:20px}.kicker,.market-head span{font-family:var(--font-display);font-size:.27rem;color:#8d4139;letter-spacing:.12em}.paper h2{font-family:var(--font-display);font-size:.46rem;margin:9px 0 17px;padding-bottom:10px;border-bottom:2px solid #383a34}.paper p{font-size:.85rem;line-height:1.25;color:#64675e}.receipt{margin:23px 0;padding:13px;text-align:center;background:rgba(255,255,255,.24)}.receipt small{font-family:var(--font-display);font-size:.24rem;color:#74766d}.receipt strong{display:block;font-family:Georgia,serif;font-style:italic;font-size:2rem}.paper .note{font-style:italic;color:#787a71}.market-head{height:52px;display:flex;justify-content:space-between;align-items:flex-start}.market-head h1{font-family:var(--font-display);font-size:.58rem;margin-top:5px}.market-head p{color:#78857d;font-style:italic;font-size:.8rem}.items{display:grid;grid-template-columns:repeat(5,1fr);grid-template-rows:repeat(2,minmax(0,1fr));gap:7px;height:calc(100% - 52px)}.item{height:auto;min-height:0;padding:0;text-align:left;color:#282b26;background:#ddd6c4;border-radius:1px;box-shadow:4px 5px 0 rgba(0,0,0,.22);position:relative;overflow:hidden;display:flex;flex-direction:column}.item:not(:disabled):hover{transform:translateY(-6px)}.item:disabled{filter:grayscale(.55) brightness(.68);cursor:not-allowed}.item.bought{filter:none;background:#9caa95}.stripe{height:4px;background:#b64d42}.index{position:absolute;right:7px;top:9px;font-family:var(--font-display);font-size:.22rem;color:#777970}.icon{font-size:1.05rem;color:#b14d43;padding:7px 8px 1px}.item h3{font-family:var(--font-display);font-size:.32rem;line-height:1.35;padding:0 8px}.item p{padding:4px 8px;font-size:.68rem;line-height:1.05;color:#666960;flex:1}.item>div:last-child{display:flex;justify-content:space-between;align-items:center;padding:5px 8px;background:rgba(40,43,38,.08)}.item>div strong{font-family:Georgia,serif;font-style:italic}.item>div small{font-family:var(--font-display);font-size:.23rem}footer{position:fixed;left:0;right:0;bottom:0;height:78px;display:grid;grid-template-columns:270px 1fr 260px;align-items:center;background:#080e0a;border-top:1px solid #354139}footer>div{height:100%;display:flex;flex-direction:column;justify-content:center;padding-left:30px;border-right:1px solid #29342d}footer small{font-family:var(--font-display);font-size:.25rem;color:#6f7d74}footer strong{font-family:var(--font-display);font-size:.4rem;margin-top:6px}footer p{text-align:center;color:#7c8980;font-style:italic}footer button{height:100%;border-radius:0;clip-path:polygon(12% 0,100% 0,100% 100%,0 100%);background:var(--orange);color:#171a16;font-size:.48rem}  @media(max-height:650px) and (min-width:1001px){header{height:70px}main{height:calc(100vh - 140px);padding:12px 0}.paper{padding:14px}.paper h2{margin:6px 0 10px}.paper p{font-size:.75rem}.receipt{margin:12px 0;padding:8px}.market-head{height:43px}.market-head p{display:none}.items{height:calc(100% - 43px)}}
  @media(max-width:1000px){.items{grid-template-columns:repeat(3,1fr)}.shop-shell{height:auto;min-height:100vh}:global(body){overflow:auto}main{height:auto}.items{padding-bottom:30px}}@media(max-width:700px){main{display:flex;flex-direction:column}.items{grid-template-columns:repeat(2,1fr)}footer{grid-template-columns:1fr 1fr 190px}footer>div{grid-column:1}footer p{display:none}footer button{grid-column:3}}
</style>
